function [ dx ] = modelo_eq( t_out, x, ws, ks,ts,reg,ns,ne,te,n_s,n_c,ns_a,ts_frozen,points,tal,est,yi,utarg,tstarg,nstarg)
[u] = ver_reg_est1(ws,yi,t_out);
[uref] = ver_reg_est1(ws,yi,t_out);
Feed =  (24.0)/60.0 ;
x_Feed = 0.5        ;
D=u(2)*Feed         ;
vol=1.6             ;
atray=0.25          ;
acond=0.5           ;
areb=1.0            ;

y(1)=((x(1)*vol/(1+(vol-1)*x(1)))  );
y(2)=((x(2)*vol/(1+(vol-1)*x(2)))  );
y(3)=((x(3)*vol/(1+(vol-1)*x(3)))  );
y(4)=((x(4)*vol/(1+(vol-1)*x(4)))  );
y(5)=((x(5)*vol/(1+(vol-1)*x(5)))  );
y(6)=((x(6)*vol/(1+(vol-1)*x(6)))  );
y(7)=((x(7)*vol/(1+(vol-1)*x(7)))  );
y(8)=((x(8)*vol/(1+(vol-1)*x(8)))  );
y(9)=((x(9)*vol/(1+(vol-1)*x(9)))  );
y(10)=((x(10)*vol/(1+(vol-1)*x(10))));
y(11)=((x(11)*vol/(1+(vol-1)*x(11))));
y(12)=((x(12)*vol/(1+(vol-1)*x(12))));
y(13)=((x(13)*vol/(1+(vol-1)*x(13))));
y(14)=((x(14)*vol/(1+(vol-1)*x(14))));
y(15)=((x(15)*vol/(1+(vol-1)*x(15))));
y(16)=((x(16)*vol/(1+(vol-1)*x(16))));
y(17)=((x(17)*vol/(1+(vol-1)*x(17))));
y(18)=((x(18)*vol/(1+(vol-1)*x(18))));
y(19)=((x(19)*vol/(1+(vol-1)*x(19))));
y(20)=((x(20)*vol/(1+(vol-1)*x(20))));
y(21)=((x(21)*vol/(1+(vol-1)*x(21))));
y(22)=((x(22)*vol/(1+(vol-1)*x(22))));
y(23)=((x(23)*vol/(1+(vol-1)*x(23))));
y(24)=((x(24)*vol/(1+(vol-1)*x(24))));
y(25)=((x(25)*vol/(1+(vol-1)*x(25))));
y(26)=((x(26)*vol/(1+(vol-1)*x(26))));
y(27)=((x(27)*vol/(1+(vol-1)*x(27))));
y(28)=((x(28)*vol/(1+(vol-1)*x(28))));
y(29)=((x(29)*vol/(1+(vol-1)*x(29))));
y(30)=((x(30)*vol/(1+(vol-1)*x(30))));
y(31)=((x(31)*vol/(1+(vol-1)*x(31))));
y(32)=((x(32)*vol/(1+(vol-1)*x(32))));
y(33)=(( D*u(1) )                   );
y(34)=((y(33)+D)                    );
y(35)=((Feed+y(33))                 );

dx(1)=( 1/acond*y(34)*(y(2)-x(1))                                        )*tal;
dx(2)=( 1/atray*(y(33)*(x(1)-x(2))-y(34)*(y(2)-y(3)))                    )*tal;
dx(3)=( 1/atray*(y(33)*(x(2)-x(3))-y(34)*(y(3)-y(4)))                    )*tal;
dx(4)=( 1/atray*(y(33)*(x(3)-x(4))-y(34)*(y(4)-y(5)))                    )*tal;
dx(5)=( 1/atray*(y(33)*(x(4)-x(5))-y(34)*(y(5)-y(6)))                    )*tal;
dx(6)=( 1/atray*(y(33)*(x(5)-x(6))-y(34)*(y(6)-y(7)))                    )*tal;
dx(7)=( 1/atray*(y(33)*(x(6)-x(7))-y(34)*(y(7)-y(8)))                    )*tal;
dx(8)=( 1/atray*(y(33)*(x(7)-x(8))-y(34)*(y(8)-y(9)))                    )*tal;
dx(9)=( 1/atray*(y(33)*(x(8)-x(9))-y(34)*(y(9)-y(10)))                   )*tal;
dx(10)=( 1/atray*(y(33)*(x(9)-x(10))-y(34)*(y(10)-y(11)))                 )*tal;
dx(11)=( 1/atray*(y(33)*(x(10)-x(11))-y(34)*(y(11)-y(12)))                )*tal;
dx(12)=( 1/atray*(y(33)*(x(11)-x(12))-y(34)*(y(12)-y(13)))                )*tal;
dx(13)=( 1/atray*(y(33)*(x(12)-x(13))-y(34)*(y(13)-y(14)))                )*tal;
dx(14)=( 1/atray*(y(33)*(x(13)-x(14))-y(34)*(y(14)-y(15)))                )*tal;
dx(15)=( 1/atray*(y(33)*(x(14)-x(15))-y(34)*(y(15)-y(16)))                )*tal;
dx(16)=( 1/atray*(y(33)*(x(15)-x(16))-y(34)*(y(16)-y(17)))                )*tal;
dx(17)=( 1/atray*(Feed*x_Feed+y(33)*x(16)-y(35)*x(17)-y(34)*(y(17)-y(18))))*tal;
dx(18)=( 1/atray*(y(35)*(x(17)-x(18))-y(34)*(y(18)-y(19)))                )*tal;
dx(19)=( 1/atray*(y(35)*(x(18)-x(19))-y(34)*(y(19)-y(20)))                )*tal;
dx(20)=( 1/atray*(y(35)*(x(19)-x(20))-y(34)*(y(20)-y(21)))                )*tal;
dx(21)=( 1/atray*(y(35)*(x(20)-x(21))-y(34)*(y(21)-y(22)))                )*tal;
dx(22)=( 1/atray*(y(35)*(x(21)-x(22))-y(34)*(y(22)-y(23)))                )*tal;
dx(23)=( 1/atray*(y(35)*(x(22)-x(23))-y(34)*(y(23)-y(24)))                )*tal;
dx(24)=( 1/atray*(y(35)*(x(23)-x(24))-y(34)*(y(24)-y(25)))                )*tal;
dx(25)=( 1/atray*(y(35)*(x(24)-x(25))-y(34)*(y(25)-y(26)))                )*tal;
dx(26)=( 1/atray*(y(35)*(x(25)-x(26))-y(34)*(y(26)-y(27)))                )*tal;
dx(27)=( 1/atray*(y(35)*(x(26)-x(27))-y(34)*(y(27)-y(28)))                )*tal;
dx(28)=( 1/atray*(y(35)*(x(27)-x(28))-y(34)*(y(28)-y(29)))                )*tal;
dx(29)=( 1/atray*(y(35)*(x(28)-x(29))-y(34)*(y(29)-y(30)))                )*tal;
dx(30)=( 1/atray*(y(35)*(x(29)-x(30))-y(34)*(y(30)-y(31)))                )*tal;
dx(31)=( 1/atray*(y(35)*(x(30)-x(31))-y(34)*(y(31)-y(32)))                )*tal;
dx(32)=( 1/areb*(y(35)*x(31)-(Feed-D)*x(32)-y(34)*y(32))                  )*tal;
dx(33)=((x(1) - 0.9)^2                                                   )*tal;
dx=transp(dx);
end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
